window.MG_LAZY_DATA["data/lazy/owner-resources/b464-80f0d359e3fd7a86.json"]={sha256:"80f0d359e3fd7a86f896eaa201410767a71c20bf3cbe9a43d7efeff4c04e7805",value:{"sources":[{"id":"b-src-environment","title":"Research on Innovative and Alternative Wastewater Technologies","url":"https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: wastewater technologies and treatment references. Not individual verification of every named environmental project."},{"id":"b-src-waste","title":"Sustainable Materials Management","url":"https://www.epa.gov/smm","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: materials life cycles, waste prevention, recycling and recovery."},{"id":"b-src-wastewater","title":"Wastewater Technology Fact Sheets","url":"https://www.epa.gov/septic/wastewater-technology-fact-sheets","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: disinfection, constructed wetlands, package plants, sewer technologies and treatment."},{"id":"v17s-urban-heat","title":"現場能源與熱泵技術","titleEn":"Onsite Energy Technologies","url":"https://betterbuildingssolutioncenter.energy.gov/onsite-energy/technologies","organization":"US DOE","accessed":"2026-10-23","publisher":"US DOE","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-urban-recovery","title":"廢熱回收技術指南","titleEn":"Waste heat recovery","url":"https://www.energy.gov.au/business/equipment-guides/waste-heat-recovery","organization":"Australian Government","accessed":"2026-10-23","publisher":"Australian Government","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}],"media":{"courses":[{"courseId":"b464","videos":[],"guides":[{"id":"b464-v17-practice","title":"工程操作與定量驗證手冊","titleEn":"Engineering actions and quantitative verification","concept":"以「污水熱源、熱泵循環與系統能效」為主線，依序完成十個專題單元。學徒在場景中辨識設備、列出邊界、重算明示的教學算例、比較量測與模型，最後診斷故障並交付證據。每一單元保留機制、算例、驗證與失效四種學習任務。","conceptEn":"Follow wastewater heat sources, heat-pump cycles and system efficiency through ten technical units. Identify equipment in the scene, define boundaries, reproduce explicitly hypothetical examples, compare measurements with models, and diagnose faults before handing over evidence. Each unit contains mechanism, calculation, verification and failure tasks.","procedure":["在「熱源時序與需求」的教學模型或試算表中先重現 125.4 kW，再依驗證任務改動一個輸入、保留其餘條件。對照「用日均流量選設備可能漏掉夜間低流量。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「二次隔離迴路」的教學模型或試算表中先重現 3 K，再依驗證任務改動一個輸入、保留其餘條件。對照「直接把污水當建築循環水會破壞隔離假設。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「熱泵能量守恆」的教學模型或試算表中先重現 160 kW，再依驗證任務改動一個輸入、保留其餘條件。對照「以COP大於1判斷違反守恆是把移熱與發熱混同。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「加熱COP」的教學模型或試算表中先重現 4 ratio，再依驗證任務改動一個輸入、保留其餘條件。對照「報壓縮機COP卻聲稱全系統性能會高估效益。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「溫升與卡諾上限」的教學模型或試算表中先重現 8.075 ratio，再依驗證任務改動一個輸入、保留其餘條件。對照「以攝氏計算卡諾COP會失去絕對溫標基礎。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「污垢熱阻」的教學模型或試算表中先重現 666.667 W/m2/K，再依驗證任務改動一個輸入、保留其餘條件。對照「只依壓差低就判斷傳熱良好可能漏掉薄污膜。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「換熱面積量級」的教學模型或試算表中先重現 40 m2，再依驗證任務改動一個輸入、保留其餘條件。對照「只用清潔U會低估運行後所需面積。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「泵功與系統COP」的教學模型或試算表中先重現 3.33333 ratio，再依驗證任務改動一個輸入、保留其餘條件。對照「忽略抽水電力可能把能量搬運成本藏起來。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「季節績效」的教學模型或試算表中先重現 3.33333 ratio，再依驗證任務改動一個輸入、保留其餘條件。對照「高COP低負荷時段等權計入會高估全年表現。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。","在「熱源影響與異常回退」的教學模型或試算表中先重現 2.39234 K，再依驗證任務改動一個輸入、保留其餘條件。對照「以固定取熱功率運行於低流量會過度降溫。」的異常情境，提交基準與變更後數值、單位及一項能區分兩者的量測。"],"procedureEn":["In the teaching model or spreadsheet for source timing and demand, first reproduce 125.4 kW, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Sizing from daily mean flow misses low-flow hours.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for secondary isolation loop, first reproduce 3 K, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Directly using sewage as building loop water defeats isolation.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for heat-pump energy balance, first reproduce 160 kW, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Calling COP above1 a violation confuses heat transfer with heat generation.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for heating cop, first reproduce 4 ratio, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Reporting compressor COP as system performance overstates benefit.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for temperature lift and carnot limit, first reproduce 8.075 ratio, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Celsius in Carnot COP loses the absolute-temperature basis.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for fouling resistance, first reproduce 666.667 W/m2/K, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Low pressure loss can miss thermally resistive thin films.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for heat-transfer area estimate, first reproduce 40 m2, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Clean U alone understates operating area needs.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for pumping and system cop, first reproduce 3.33333 ratio, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Ignoring pumping hides the energy cost of transport.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for seasonal performance, first reproduce 3.33333 ratio, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Equal weighting of high-COP low-load periods overstates annual performance.\" and submit baseline and changed values, units, and one measurement that distinguishes them.","In the teaching model or spreadsheet for source impacts and fault fallback, first reproduce 2.39234 K, then vary one input following the verification task while holding other conditions fixed. Contrast the fault scenario \"Fixed extraction at low flow can cause excessive cooling.\" and submit baseline and changed values, units, and one measurement that distinguishes them."],"evidence":["疊合24小時熱源和需求曲線。","改變換熱器面積比較接近溫差。","檢查熱源側、熱端及電表三項是否閉合。","把循環泵納入後重算系統COP。","把熱端升高10K，觀察理想上限變化。","在相同流量比較清洗前後UA及壓差。","把污垢後U減半，重算面積需求。","比較遠近熱源的泵電與供熱量。","比較直接平均4與2.5和能量加權結果。","模擬污水低流量，檢查取熱後溫度與回退條件。"],"evidenceEn":["Overlay24-hour source and demand profiles.","Vary exchanger area and compare approach temperature.","Check closure of source, sink and electricity measurements.","Include circulation pumps and recalculate system COP.","Raise sink temperature10K and observe the ideal bound.","Compare UA and pressure before/after cleaning at equal flow.","Halve fouled U and recalculate required area.","Compare pumping and heat delivery for near and distant sources.","Compare the simple average of4 and2.5 with the energy-weighted result.","Simulate low sewage flow and check outlet temperature and fallback conditions."],"pitfalls":["用日均流量選設備可能漏掉夜間低流量。","直接把污水當建築循環水會破壞隔離假設。","以COP大於1判斷違反守恆是把移熱與發熱混同。","報壓縮機COP卻聲稱全系統性能會高估效益。","以攝氏計算卡諾COP會失去絕對溫標基礎。","只依壓差低就判斷傳熱良好可能漏掉薄污膜。","只用清潔U會低估運行後所需面積。","忽略抽水電力可能把能量搬運成本藏起來。","高COP低負荷時段等權計入會高估全年表現。","以固定取熱功率運行於低流量會過度降溫。"],"pitfallsEn":["Sizing from daily mean flow misses low-flow hours.","Directly using sewage as building loop water defeats isolation.","Calling COP above1 a violation confuses heat transfer with heat generation.","Reporting compressor COP as system performance overstates benefit.","Celsius in Carnot COP loses the absolute-temperature basis.","Low pressure loss can miss thermally resistive thin films.","Clean U alone understates operating area needs.","Ignoring pumping hides the energy cost of transport.","Equal weighting of high-COP low-load periods overstates annual performance.","Fixed extraction at low flow can cause excessive cooling."],"sourceIds":["v17s-urban-heat","v17s-urban-recovery"],"sources":[{"id":"v17s-urban-heat","title":"現場能源與熱泵技術","titleEn":"Onsite Energy Technologies","url":"https://betterbuildingssolutioncenter.energy.gov/onsite-energy/technologies","organization":"US DOE","accessed":"2026-10-23","publisher":"US DOE","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-urban-recovery","title":"廢熱回收技術指南","titleEn":"Waste heat recovery","url":"https://www.energy.gov.au/business/equipment-guides/waste-heat-recovery","organization":"Australian Government","accessed":"2026-10-23","publisher":"Australian Government","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}],"simulationOnly":true,"scope":"公開原理與資料支持的原創教學。算例中的輸入為明示教學假設，非該設施實測或操作設定。此處任務在離線模型完成，不能作為現場設計、飲用水合格或設備操作許可。","scopeEn":"Original teaching based on public principles and sources. Numerical inputs are explicit teaching assumptions, not site measurements or operating setpoints. Tasks use offline models and do not certify field design, potable-water compliance or equipment operation."}]}]},"related":{"courses":[{"courseId":"b464","overview":"跨單元連結與比較練習","overviewEn":"Cross-process connections and comparisons","related":[{"id":"b415","title":"首爾清溪川復育","titleEn":"Seoul Cheonggyecheon restoration","why":"比較兩個系統的物質或能量收支，列出不可直接沿用的邊界條件。","whyEn":"Compare material or energy balances and identify boundary conditions that cannot be transferred.","transfer":"守恆、量測與失效驗證","transferEn":"Conservation, measurement and failure verification","difference":"設備尺度、進料組成與品質目標必須分別設定。","differenceEn":"Equipment scale, feed composition and quality objectives require separate definitions.","practice":["各選一個教學算例，記下輸入、輸出與單位。","對照兩課的系統邊界，說明哪些假設不能沿用。","改變一個輸入，提出量測與失效判據來核對結果。"],"practiceEn":["Choose one worked example from each course and record inputs, outputs and units.","Compare system boundaries and identify assumptions that cannot transfer.","Change one input and propose measurements and failure criteria to check the result."],"place":{"name":"首爾代表點","nameEn":"Seoul reference point","country":"南韓","countryEn":"South Korea","lat":37.57,"lon":126.98,"coordinateScope":"approximate-city-reference; not a facility entrance","lng":126.98,"coordinateScopeEn":"Approximate public facility/research reference, not an operating entrance or the teaching laboratory."},"referenceUrls":["https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","https://www.epa.gov/smm","https://www.epa.gov/septic/wastewater-technology-fact-sheets"]},{"id":"b416","title":"新加坡碧山—宏茂橋公園河川復育","titleEn":"Bishan–Ang Mo Kio Park river restoration","why":"比較兩個系統的物質或能量收支，列出不可直接沿用的邊界條件。","whyEn":"Compare material or energy balances and identify boundary conditions that cannot be transferred.","transfer":"守恆、量測與失效驗證","transferEn":"Conservation, measurement and failure verification","difference":"設備尺度、進料組成與品質目標必須分別設定。","differenceEn":"Equipment scale, feed composition and quality objectives require separate definitions.","practice":["各選一個教學算例，記下輸入、輸出與單位。","對照兩課的系統邊界，說明哪些假設不能沿用。","改變一個輸入，提出量測與失效判據來核對結果。"],"practiceEn":["Choose one worked example from each course and record inputs, outputs and units.","Compare system boundaries and identify assumptions that cannot transfer.","Change one input and propose measurements and failure criteria to check the result."],"place":{"name":"新加坡","nameEn":"Singapore","country":"新加坡","countryEn":"Singapore","lat":1.35,"lon":103.82,"coordinateScope":"approximate-city-reference; not a facility entrance","lng":103.82,"coordinateScopeEn":"Approximate public facility/research reference, not an operating entrance or the teaching laboratory."},"referenceUrls":["https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","https://www.epa.gov/smm","https://www.epa.gov/septic/wastewater-technology-fact-sheets"]}],"references":[{"id":"b-src-environment","title":"Research on Innovative and Alternative Wastewater Technologies","url":"https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: wastewater technologies and treatment references. Not individual verification of every named environmental project."},{"id":"b-src-waste","title":"Sustainable Materials Management","url":"https://www.epa.gov/smm","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: materials life cycles, waste prevention, recycling and recovery."},{"id":"b-src-wastewater","title":"Wastewater Technology Fact Sheets","url":"https://www.epa.gov/septic/wastewater-technology-fact-sheets","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: disinfection, constructed wetlands, package plants, sewer technologies and treatment."},{"id":"v17s-urban-heat","title":"現場能源與熱泵技術","titleEn":"Onsite Energy Technologies","url":"https://betterbuildingssolutioncenter.energy.gov/onsite-energy/technologies","organization":"US DOE","accessed":"2026-10-23","publisher":"US DOE","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-urban-recovery","title":"廢熱回收技術指南","titleEn":"Waste heat recovery","url":"https://www.energy.gov.au/business/equipment-guides/waste-heat-recovery","organization":"Australian Government","accessed":"2026-10-23","publisher":"Australian Government","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}]}]},"places":{"courses":[{"courseId":"b464","place":{"name":"美國能源部Forrestal大樓：方法資料來源機構（非實廠）","nameEn":"US DOE Forrestal Building: methodology source institution (not a process plant)","country":"美國","countryEn":"United States","lat":38.89,"lon":-77.03,"coordinateScope":"近似機構所在區域位置；依公開地址作教材地圖代表點，非建物入口、實廠、實測或導航位置。","coordinateScopeEn":"Approximate institution-area location inferred from its public address for the teaching map; not a building entrance, process plant, surveyed point or navigation coordinate.","locationSourceUrl":"https://science.osti.gov/wdts/vfp/Contact","locationVerified":"2026-10-23","lng":-77.03},"summary":"本課以來源所列的技術指引與研究為閱讀脈絡，並非重建某一設施的工程沿革；算例、數據與場景參數皆為原創教學假設。比較舊方法與感測、控制、資源回收整合的方法時，先固定處理功能及系統邊界，再評估效率與可靠度。","summaryEn":"The cited technical guidance and research provide a reading pathway, not the engineering history of a particular facility. Examples, data and scene parameters are original teaching assumptions. When comparing conventional methods with integrated sensing, control and resource recovery, hold the treatment function and system boundary fixed before assessing efficiency and reliability.","history":[{"year":"工程背景","title":"污水熱回收熱泵","titleEn":"Wastewater heat-recovery heat pumps","text":"本課以來源所列的技術指引與研究為閱讀脈絡，並非重建某一設施的工程沿革；算例、數據與場景參數皆為原創教學假設。比較舊方法與感測、控制、資源回收整合的方法時，先固定處理功能及系統邊界，再評估效率與可靠度。","textEn":"The cited technical guidance and research provide a reading pathway, not the engineering history of a particular facility. Examples, data and scene parameters are original teaching assumptions. When comparing conventional methods with integrated sensing, control and resource recovery, hold the treatment function and system boundary fixed before assessing efficiency and reliability."}],"connection":"以「污水熱源、熱泵循環與系統能效」為主線，依序完成十個專題單元。學徒在場景中辨識設備、列出邊界、重算明示的教學算例、比較量測與模型，最後診斷故障並交付證據。每一單元保留機制、算例、驗證與失效四種學習任務。","connectionEn":"Follow wastewater heat sources, heat-pump cycles and system efficiency through ten technical units. Identify equipment in the scene, define boundaries, reproduce explicitly hypothetical examples, compare measurements with models, and diagnose faults before handing over evidence. Each unit contains mechanism, calculation, verification and failure tasks.","references":[{"id":"v17s-urban-heat","title":"現場能源與熱泵技術","titleEn":"Onsite Energy Technologies","url":"https://betterbuildingssolutioncenter.energy.gov/onsite-energy/technologies","organization":"US DOE","accessed":"2026-10-23","publisher":"US DOE","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-urban-recovery","title":"廢熱回收技術指南","titleEn":"Waste heat recovery","url":"https://www.energy.gov.au/business/equipment-guides/waste-heat-recovery","organization":"Australian Government","accessed":"2026-10-23","publisher":"Australian Government","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}],"sourceIds":["v17s-urban-heat","v17s-urban-recovery"]}]},"vendors":{"courses":[],"vendors":[]}}};
